(function(){
'use strict';
const M=window.DaywearModel, q=s=>document.querySelector(s),KEY='daywear-local-training-v1';
let rows=[],model=null,current=null,photoToken=0,busy=false;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function message(text){q('#training-message').textContent=text}
function write(nextRows,nextModel){try{localStorage.setItem(KEY,JSON.stringify({version:1,rows:nextRows,model:nextModel}));rows=nextRows;model=nextModel;return true}catch{message('Could not save training data. Enable browser storage or free space, then try again.');return false}}
function resetResult(){q('#check-result').replaceChildren(node('div','✳','result-symbol'),node('h3','Ready for your next look'),node('p','Select a photo and check it against your trained examples. Changing the photo or occasion clears the previous result.'))}
function render(){q('#example-count').textContent=rows.length+' examples';q('#model-status').textContent=model?'Trained · '+rows.length+' examples':'Not trained yet';q('#check-analyze').disabled=!model||!current||busy;q('#example-add').disabled=!current||busy;q('#model-train').disabled=busy||rows.length<6;q('#example-list').replaceChildren();for(const row of rows){const wrap=node('div',undefined,'example-row'),label=node('span',row.name+' · '+row.occasion),rating=node('strong',row.rating+'/10'),remove=node('button','×');remove.type='button';remove.setAttribute('aria-label','Remove example '+row.name);remove.onclick=()=>{if(write(rows.filter(r=>r.id!==row.id),null)){resetResult();message('Example removed. Train again to update the model.');render()}};wrap.append(label,rating,remove);q('#example-list').append(wrap)}q('#check-message').textContent=!model?'Add at least 6 different rated photos, then train your model.':!current?'Choose a new outfit photo to check.':'Ready. Your photo will be processed only in this browser.'}
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){if(saved.version!==1||!Array.isArray(saved.rows)||saved.rows.length>300||!saved.rows.every(M.valid))throw Error('Invalid saved data');rows=saved.rows;if(saved.model?.version===1&&Array.isArray(saved.model.rows)&&JSON.stringify(saved.model.rows)===JSON.stringify(rows)&&rows.length>=6)model=M.train(rows)}}catch{message('Saved training data could not be loaded. You can import a backup or add new examples.')}
async function load(file){const token=++photoToken;current=null;resetResult();q('#check-photo').hidden=true;q('#check-placeholder').hidden=false;if(!file){render();return}if(!file.type.startsWith('image/')||file.size>15*1024*1024){render();q('#check-message').textContent='Choose an image smaller than 15 MB.';return}busy=true;render();q('#check-message').textContent='Reading your photo locally…';try{const img=await createImageBitmap(file);if(token!==photoToken){img.close();return}const canvas=document.createElement('canvas');canvas.width=128;canvas.height=192;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#f5f4f0';ctx.fillRect(0,0,128,192);const scale=Math.min(128/img.width,192/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(128-w)/2,(192-h)/2,w,h);img.close();const vector=M.features(ctx.getImageData(0,0,128,192).data,128,192);current={features:vector,name:file.name.replace(/\.[^.]*$/,'').slice(0,80)};q('#check-photo').src=canvas.toDataURL('image/jpeg',.85);q('#check-photo').hidden=false;q('#check-placeholder').hidden=true;q('#example-name').value=current.name}catch{q('#check-message').textContent='Could not read this photo. Try a JPG, PNG or WebP.'}finally{if(token===photoToken){busy=false;const failed=!current;render();if(failed)q('#check-message').textContent='Could not read this photo. Try a JPG, PNG or WebP.'}}}
q('#check-file').onchange=e=>load(e.target.files[0]);q('#check-camera').onchange=e=>load(e.target.files[0]);q('#check-camera-btn').onclick=()=>q('#check-camera').click();q('#check-occasion').onchange=resetResult;q('#example-rating').oninput=e=>q('#rating-value').textContent=e.target.value+' / 10';
q('#example-add').onclick=()=>{if(!current)return;const name=q('#example-name').value.trim();if(!name){message('Give this example a short label first.');return}if(rows.length>=300){message('This prototype supports up to 300 examples. Export a backup before removing any.');return}if(rows.some(r=>M.distance(r.features,current.features)<.003)){message('This photo is already represented. Use a different outfit photo, not a duplicate.');return}const row={id:crypto.randomUUID(),name,rating:Number(q('#example-rating').value),occasion:q('#check-occasion').value,features:current.features};if(write([...rows,row],null)){resetResult();render();message('Example added. '+Math.max(0,6-rows.length)+' more needed to reach the minimum. Train again after adding or changing examples.')}};
q('#model-train').onclick=async()=>{try{busy=true;render();message('Training your personal model…');await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)));const trained=M.train(rows),error=M.evaluate(rows);if(write(rows,trained)){resetResult();message('Training complete. '+rows.length+' examples. '+(error===null?'Add a seventh example to calculate leave-one-out error.':'Leave-one-out average error: '+error+' rating points (small, personal dataset; not independent validation).'))}}catch(e){message(e.message)}finally{busy=false;render()}};
q('#check-analyze').onclick=()=>{try{if(!current||!model)return;const result=M.predict(model,current.features,q('#check-occasion').value),box=q('#check-result');box.replaceChildren();const score=node('div',String(result.rating),'result-score');score.append(node('small',' / 10'));box.append(node('p','PERSONAL MODEL ESTIMATE','eyebrow'),score,node('h3','Learned from your ratings'));const duplicate=result.distance<.003;box.append(node('p',duplicate?'This photo matches a training example. Its score is a recall of your rating, not a test on a new outfit.':result.distance>.22?'This photo differs substantially from your examples. Treat this score as uncertain and add more varied training photos.':'Compared with your three nearest rated photos. This is an experimental preference estimate, not an objective judgment.'));if(!result.matchedOccasion)box.append(node('p','Not enough examples for this occasion; the model used all occasions.'));box.append(node('h3','Closest examples'));const list=node('ul');result.nearest.forEach(r=>list.append(node('li',r.name+' — your rating '+r.rating+'/10')));box.append(list);const best=result.nearest.slice().sort((a,b)=>b.rating-a.rating)[0];box.append(node('h3','Ideas to try (general styling prompts)'));const suggestions=node('ul');suggestions.append(node('li','Use “'+best.name+'” as a reference for a combination you rated '+best.rating+'/10.'),node('li','Try changing one piece at a time, then take another photo to compare.'),node('li',({Casual:'Try a simple base and one accent color.',Work:'Check your dress code and try a coordinated shoe and accessory combination.',Evening:'Try one focal piece and keep the remaining pieces simple.',Sport:'Prioritize comfortable movement and activity-appropriate footwear.'})[q('#check-occasion').value]));box.append(suggestions)}catch(e){q('#check-message').textContent=e.message}};
q('#model-export').onclick=()=>{if(!rows.length){message('Add examples before exporting.');return}const blob=new Blob([JSON.stringify({version:1,rows},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='daywear-training.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Exported image features and your labels. Original photos are not included. Treat the backup as personal data.')};
q('#model-import-btn').onclick=()=>q('#model-import').click();q('#model-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3*1024*1024)throw Error('Use a training file smaller than 3 MB.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.rows)||data.rows.length>300||!data.rows.every(M.valid))throw Error('This is not a valid Daywear training file.');if(new Set(data.rows.map(r=>r.id)).size!==data.rows.length)throw Error('Duplicate example IDs in this file.');if(rows.length&&!confirm('Replace your current training examples with this file? Export a backup first if needed.'))return;if(write(data.rows,null)){resetResult();render();message('Imported '+rows.length+' examples. Click Train my model to use them.')}}catch(e){message(e.message)}finally{e.target.value=''}};
q('#model-clear').onclick=()=>{if(!confirm('Delete all local training examples and the trained model? Your wardrobe will stay saved.'))return;if(write([],null)){resetResult();render();message('Training data deleted from this browser. Exported backups are separate.')}};
render();
})();
